//! Process-wide identifiers: message ids and receipt handles.

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct MessageId(u64);

impl fmt::Display for MessageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "m-{}", self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ReceiptHandle(u64);

impl ReceiptHandle {
    /// Reads a handle sent by a client. Only the exact text `r-<n>` of a handle
    /// that was issued is accepted: no sign, no leading zeros, no whitespace.
    pub fn parse(text: &str, issued: &Ids) -> Option<Self> {
        let digits = text.strip_prefix("r-")?;
        if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        let number: u64 = digits.parse().ok()?;
        (1..=issued.receipts).contains(&number).then_some(Self(number))
    }
}

impl fmt::Display for ReceiptHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "r-{}", self.0)
    }
}

/// Counters behind the identifiers; one per process, shared by all queues.
#[derive(Debug, Default)]
pub struct Ids {
    messages: u64,
    receipts: u64,
}

impl Ids {
    pub fn next_message(&mut self) -> MessageId {
        self.messages += 1;
        MessageId(self.messages)
    }

    pub fn next_receipt(&mut self) -> ReceiptHandle {
        self.receipts += 1;
        ReceiptHandle(self.receipts)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_count_independently_from_one() {
        let mut ids = Ids::default();
        assert_eq!(ids.next_message().to_string(), "m-1");
        assert_eq!(ids.next_message().to_string(), "m-2");
        assert_eq!(ids.next_receipt().to_string(), "r-1");
    }

    #[test]
    fn only_exact_issued_handles_parse() {
        let mut ids = Ids::default();
        for _ in 0..12 {
            ids.next_receipt();
        }
        assert_eq!(ReceiptHandle::parse("r-1", &ids).map(|h| h.to_string()), Some("r-1".into()));
        assert!(ReceiptHandle::parse("r-12", &ids).is_some());
        for bad in ["r-0", "r-13", "r-01", "R-1", "r-1 ", " r-1", "r-+1", "r-", "r--1", "1", ""] {
            assert!(ReceiptHandle::parse(bad, &ids).is_none(), "{bad:?}");
        }
    }
}
EOF
cat > src/params.rs <<'EOF'
//! Typed access to the members of a JSON object, following the protocol rules:
//! a `null` member counts as absent, and a present member of the wrong type or
//! outside its range is `InvalidParameterValue`.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode, Result};

#[derive(Debug, Clone, Copy)]
pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    /// Fails with `MissingParameter` for the first of `names` that is absent.
    /// Called before any value is read, so a missing parameter always wins over
    /// an invalid one.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(Error::missing(name)),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|value| {
                value
                    .as_str()
                    .ok_or_else(|| Error::invalid_value(name, "must be a string"))
            })
            .transpose()
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?.ok_or_else(|| Error::missing(name))
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|value| {
                value
                    .as_bool()
                    .ok_or_else(|| Error::invalid_value(name, "must be a boolean"))
            })
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<&'a Map<String, Value>>> {
        self.get(name)
            .map(|value| {
                value
                    .as_object()
                    .ok_or_else(|| Error::invalid_value(name, "must be an object"))
            })
            .transpose()
    }

    /// An integer written without fraction or exponent, within `range`.
    pub fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        self.get(name)
            .map(|value| {
                value
                    .as_u64()
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| range.contains(n))
                    .ok_or_else(|| {
                        Error::invalid_value(
                            name,
                            &format!(
                                "must be an integer from {} to {}",
                                range.start(),
                                range.end()
                            ),
                        )
                    })
            })
            .transpose()
    }

    pub fn required_integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32> {
        self.integer(name, range)?
            .ok_or_else(|| Error::missing(name))
    }

    /// Fails with `InvalidParameterValue` for a present member not in `known`.
    pub fn reject_unknown(&self, known: &[&str]) -> Result<()> {
        let unknown = self
            .0
            .iter()
            .find(|(name, value)| !value.is_null() && !known.contains(&name.as_str()));
        match unknown {
            Some((name, _)) => Err(Error::new(
                ErrorCode::InvalidParameterValue,
                format!("{name} is not a known attribute"),
            )),
            None => Ok(()),
        }
    }
}
EOF
