    Ok(Command::SendMessage(SendRequest {
        queue,
        body: body.to_owned(),
        delay_seconds: params.integer("DelaySeconds", 0..=900)?,
        group_id: message_id_string(params, "GroupId")?,
        deduplication_id: message_id_string(params, "DeduplicationId")?,
